import * as z from "zod/v4";
const DATE = z.regexes.date.source.slice(1, -1);
const TIME = String.raw `(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d(?:\.\d+)?)?`;
const OFFSET = String.raw `[+-]\d{2}:?\d{2}`;
/**
 * The datetime check of zod 3's `z.string().datetime()`. zod 4 refuses times
 * without seconds and, with `offset`, `+HHMM` offsets; models and people still
 * type both. Use it for values a person or a model writes; a value that only
 * `toISOString()` writes can keep `z.iso.datetime()`.
 */
export function zod3Datetime(options = {}) {
    const zone = options.offset === true ? `(?:Z|${OFFSET})` : "Z";
    return z
        .string()
        .regex(new RegExp(`^${DATE}T${TIME}${zone}$`), options.message ?? "Invalid datetime")
        .meta({ format: "date-time" });
}
